import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,e as s}from"./app-401f6a81.js";const d={},t=s(`<h1 id="tldr-简化的命令手册-community-cheatsheets" tabindex="-1"><a class="header-anchor" href="#tldr-简化的命令手册-community-cheatsheets" aria-hidden="true">#</a> tldr（简化的命令手册（community cheatsheets））</h1><blockquote><p>Homebrew 版本 1.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install tldr</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>tldr（Too Long; Didn&#39;t Read）是一个&quot;简化的命令行手册&quot;工具：它把 Linux/Unix 命令的官方 <code>man</code> 手册浓缩成一张张<strong>精简的速查表（cheatsheet）</strong>，只保留最常用、最实用的参数和示例，让你一眼就能上手某个命令，而不是在几千行的 man 手册里大海捞针。它解决的是&quot;知道有某个命令但记不住用法&quot;&quot;懒得翻 man 手册&quot;的痛点，典型应用场景是：快速复习 <code>tar</code>、<code>git</code>、<code>awk</code> 等常用命令的常见组合，或在新装的服务器上快速确认某个工具怎么用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> tldr

<span class="token comment"># 升级</span>
brew upgrade tldr

<span class="token comment"># 卸载</span>
brew uninstall tldr

<span class="token comment"># 验证安装成功（查看版本）</span>
tldr <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装后 <code>tldr</code> 即进入 PATH，直接可全局调用。若之前用 <code>npm install -g tldr</code> 装过别的实现，建议先卸载旧版再 <code>brew install</code> 以免命令冲突。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>tldr 命令名</code></td><td>查看某个命令的简化手册</td><td><code>tldr tar</code></td></tr><tr><td><code>-p, --platform=平台</code></td><td>指定操作系统平台（linux / osx / sunos / windows / common）</td><td><code>tldr -p osx open</code></td></tr><tr><td><code>-r, --render=路径</code></td><td>渲染本地的手册文件（用于测试/自建）</td><td><code>tldr -r ./mypage.md tar</code></td></tr><tr><td><code>-u, --update</code></td><td>更新本地手册数据库</td><td><code>tldr --update</code></td></tr><tr><td><code>-c, --clear-cache</code></td><td>清空本地数据库缓存</td><td><code>tldr --clear-cache</code></td></tr><tr><td><code>-l, --list</code></td><td>列出本地数据库里的全部命令条目</td><td><code>tldr --list</code></td></tr><tr><td><code>-C, --color</code></td><td>强制彩色输出</td><td><code>tldr -C git</code></td></tr><tr><td><code>-V, --verbose</code></td><td>更新/清空缓存时显示详细过程</td><td><code>tldr -u -V</code></td></tr></tbody></table><blockquote><p>提示：<code>-V</code>（大写）是 verbose，<code>-v</code>（小写）才是版本号。</p></blockquote><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-查看-tar-命令的常用用法" tabindex="-1"><a class="header-anchor" href="#示例-1-查看-tar-命令的常用用法" aria-hidden="true">#</a> 示例 1：查看 <code>tar</code> 命令的常用用法</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：无需任何准备，tldr 首次使用时会自动下载数据库</span>
tldr <span class="token function">tar</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>tar

  Archiving utility. Often combined with a compression method, such as gzip or bzip.
  More information: https://www.gnu.org/software/tar/.

  - Create an archive from files:
      tar cf target.tar file1 file2 file3

  - Create a gzipped archive:
      tar czf target.tar.gz file1 file2 file3

  - Extract a (compressed) archive into the current directory:
      tar xzf source.tar.gz
  ...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-按平台查看-macos-与-linux-命令差异" tabindex="-1"><a class="header-anchor" href="#示例-2-按平台查看-macos-与-linux-命令差异" aria-hidden="true">#</a> 示例 2：按平台查看（macOS 与 Linux 命令差异）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># macOS 上查看 open 命令的速查（open 是 mac 专属）</span>
tldr <span class="token parameter variable">-p</span> osx <span class="token function">open</span>

<span class="token comment"># 查看 Linux 平台下的 ifconfig（不同平台参数不同）</span>
tldr <span class="token parameter variable">-p</span> linux <span class="token function">ifconfig</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-更新缓存并查看全部可用命令" tabindex="-1"><a class="header-anchor" href="#示例-3-更新缓存并查看全部可用命令" aria-hidden="true">#</a> 示例 3：更新缓存并查看全部可用命令</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 更新本地数据库到最新</span>
tldr <span class="token parameter variable">--update</span>

<span class="token comment"># 列出本地已有全部命令条目（方便发现新工具）</span>
tldr <span class="token parameter variable">--list</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-快速对比多个相似命令" tabindex="-1"><a class="header-anchor" href="#示例-4-快速对比多个相似命令" aria-hidden="true">#</a> 示例 4：快速对比多个相似命令</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 一口气查三个压缩/归档相关命令，快速对比用法</span>
tldr <span class="token function">tar</span> <span class="token operator">&amp;&amp;</span> tldr <span class="token function">zip</span> <span class="token operator">&amp;&amp;</span> tldr <span class="token function">gzip</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><p><strong>1. 用 shell 别名绑定常用命令速查</strong></p><p>在 <code>~/.zshrc</code> 或 <code>~/.bashrc</code> 里加：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">alias</span> <span class="token assign-left variable">tl</span><span class="token operator">=</span><span class="token string">&#39;tldr&#39;</span>        <span class="token comment"># 少敲几个字</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">man2</span><span class="token operator">=</span><span class="token string">&#39;tldr&#39;</span>      <span class="token comment"># 把 tldr 当&quot;精简 man&quot;用</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 与 <code>which</code>/<code>command -v</code> 搭配快速查工具</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先确认命令确实存在，再查用法</span>
<span class="token builtin class-name">command</span> <span class="token parameter variable">-v</span> jq <span class="token operator">&amp;&amp;</span> tldr jq
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 与 fzf 联动，本地数据库交互式浏览</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 fzf 在本地命令列表里模糊选择再查看</span>
tldr <span class="token parameter variable">--list</span> <span class="token operator">|</span> fzf <span class="token operator">|</span> <span class="token function">xargs</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> tldr <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. 数据库与缓存管理</strong></p><ul><li>首次运行 <code>tldr</code> 时自动下载数据库并缓存到本地；之后离线也能查。</li><li>若内容过旧或想强制刷新，运行 <code>tldr --update</code>。</li><li>清理缓存用 <code>tldr --clear-cache</code>，配合 <code>-V</code> 可看清理了哪些文件。</li><li>Homebrew 版的数据库默认放在 Homebrew 缓存目录下，一般无需手动干预。</li></ul><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><p><strong>1. 首次使用需要联网</strong></p><p>第一次运行 <code>tldr</code> 会从网络拉取数据库，如果没网或代理配置不对，会报错或卡住。解决办法：检查网络/代理后重试，或先 <code>tldr --update</code> 手动触发下载。</p><p><strong>2. <code>-v</code> 与 <code>-V</code> 别搞混</strong></p><ul><li><code>tldr -v</code>：打印版本号。</li><li><code>tldr -V</code>（大写）：配合 <code>-u</code>/<code>-c</code> 显示详细输出。<br> 新手常把大写当版本号用而报错。</li></ul><p><strong>3. 命令名大小写与平台差异</strong></p><p>tldr 的速查表按平台区分，<code>osx</code>（macOS）与 <code>linux</code> 的同名命令参数可能不同。在 macOS 上查 Linux 专用命令（如 <code>apt</code>）时，记得加 <code>-p linux</code> 否则可能提示找不到。</p><p><strong>4. 找不到某个命令</strong></p><p>如果 <code>tldr foo</code> 提示找不到，可能原因：</p><ul><li>该命令确实没有对应的速查表（tldr 覆盖的是社区常见命令）。</li><li>数据库太旧，先 <code>tldr --update</code> 再试。</li><li>也可以用 <code>tldr --list | grep foo</code> 确认是否收录。</li></ul><p><strong>5. 它只是速查表，不是完整手册</strong></p><p>tldr 只提供最常用参数，不覆盖 man 的全部细节。遇到边界情况、高级配置或版本差异时，仍应以 <code>man 命令名</code> 或官方文档为准——把 tldr 当作&quot;快速上手入口&quot;，man 当作&quot;权威参考&quot;。</p><p><strong>6. 数据库是社区维护的，可能有瑕疵</strong></p><p>tldr 的速查表由 tldr-pages 社区众包维护，个别条目可能过时或不完整。命令行为与预期不符时，多结合 <code>man</code> 和 <code>--version</code> 交叉核对。</p>`,45),i=[t];function r(c,l){return a(),n("div",null,i)}const u=e(d,[["render",r],["__file","tldr.html.vue"]]);export{u as default};
